      "content": "import { expect, test } from 'bun:test';
import { DomainError } from '@agentic-ddd/core';
import { covers } from '@agentic-ddd/testing';
import { Task } from '../domain/task';
import { TaskCompleted } from '../domain/task.events';

test(covers(['method:Task.complete'], 'conclui uma tarefa pending e registra TaskCompleted com seu id'), () => {
  const task = Task.create('task-complete-1', 'Concluir tarefa');
  task.pullEvents();
  expect(task.status).toBe('pending');

  expect(task.complete()).toBeUndefined();

  expect(task.status).toBe('completed');
  const events = task.pullEvents();
  expect(events).toHaveLength(1);
  expect(events[0]).toBeInstanceOf(TaskCompleted);
  expect(events[0]!.payload).toEqual({ taskId: 'task-complete-1' });
  expect(task.pullEvents()).toEqual([]);
});

test(covers([
  'method:Task.complete',
  'criterion:0001/conclusao',
], 'rejeita repetição com TASK_ALREADY_COMPLETED e preserva estado e evento registrado'), () => {
  const task = Task.create('task-complete-2', 'Concluir uma vez');
  task.pullEvents();
  expect(task.status).toBe('pending');
  task.complete();

  let failure: unknown;
  try {
    task.complete();
  } catch (error) {
    failure = error;
  }

  expect(failure).toBeInstanceOf(DomainError);
  expect(failure).toHaveProperty('code', 'TASK_ALREADY_COMPLETED');
  expect(task.status).toBe('completed');
  const events = task.pullEvents();
  expect(events).toHaveLength(1);
  expect(events[0]).toBeInstanceOf(TaskCompleted);
  expect(events[0]!.payload).toEqual({ taskId: 'task-complete-2' });
  expect(task.pullEvents()).toEqual([]);
});
